contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 value) public {
        require(to != address(0), "zero recipient");
        uint256 fromBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);
        bool reverted;
        try c.transfer(to, value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (!reverted) {
            uint256 fromAfter = c.balanceOf(address(this));
            uint256 toAfter = c.balanceOf(to);
            if (address(this) == to) {
                assert(fromAfter == fromBefore && toAfter == toBefore);
            } else {
                assert(fromAfter == fromBefore - value && toAfter == toBefore + value);
            }
        }
    }
}

contract InvMutTest {
