                c.totalSupply() == totalSupplyBefore - amount
            );
        } else {
            assert(
                c.balanceOf(address(this)) == ownerBalBefore &&
                c.totalSupply() == totalSupplyBefore
            );
        }
    }

    receive() external payable {}
}

